import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.DaGSOal_.js";const m=JSON.parse('{"title":"C","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/c.md","filePath":"glossaire-a-z/c.md"}'),i={name:"glossaire-a-z/c.md"};function o(l,e,s,c,d,u){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h1><h2 id="cardano" tabindex="-1">Cardano <a class="header-anchor" href="#cardano" aria-label="Permalink to &quot;Cardano&quot;">​</a></h2><p>Cardano est une blockchain de couche 1 publique et sans permission, fondée sur la recherche évaluée par les pairs.</p><p>→ <a href="https://cardano.org/glossary/cardano/" target="_blank" rel="noreferrer">Cardano — Glossaire officiel</a></p><h2 id="cbdc-fr-monnaie-numerique-de-banque-centrale" tabindex="-1">CBDC (fr : Monnaie numérique de banque centrale) <a class="header-anchor" href="#cbdc-fr-monnaie-numerique-de-banque-centrale" aria-label="Permalink to &quot;CBDC (fr : Monnaie numérique de banque centrale)&quot;">​</a></h2><p>Une CBDC est une forme numérique de monnaie fiduciaire émise et contrôlée par une banque centrale. Contrairement aux cryptomonnaies sans permission, les CBDC sont administrées de manière centralisée et leurs règles peuvent être modifiées par leur émetteur.</p><h2 id="cex-fr-plateforme-d-echange-centralisee" tabindex="-1">CEX (fr : Plateforme d’échange centralisée) <a class="header-anchor" href="#cex-fr-plateforme-d-echange-centralisee" aria-label="Permalink to &quot;CEX (fr : Plateforme d’échange centralisée)&quot;">​</a></h2><p>Une plateforme d’échange centralisée est une plateforme de négociation dans laquelle une entreprise conserve les actifs des utilisateurs et gère le carnet d’ordres en interne. Contrairement à une plateforme décentralisée (DEX), les utilisateurs ne détiennent pleinement leurs ada dans leur propre portefeuille qu’après les avoir retirés de la plateforme.</p><h2 id="chang" tabindex="-1">Chang <a class="header-anchor" href="#chang" aria-label="Permalink to &quot;Chang&quot;">​</a></h2><p>Chang est le hard fork du 1er septembre 2024 qui a activé l’ère Conway et introduit la gouvernance sur chaîne de Cardano, conformément à la CIP-1694.</p><h2 id="cip-fr-proposition-d-amelioration-de-cardano" tabindex="-1">CIP (fr : Proposition d’amélioration de Cardano) <a class="header-anchor" href="#cip-fr-proposition-d-amelioration-de-cardano" aria-label="Permalink to &quot;CIP (fr : Proposition d’amélioration de Cardano)&quot;">​</a></h2><p>Une CIP est une proposition formelle décrivant une modification, une norme ou une fonctionnalité de Cardano. Les CIP constituent le mécanisme de référence permettant de débattre, d’affiner et d’adopter les règles et conventions de l’écosystème.</p><p>→ <a href="https://cips.cardano.org/" target="_blank" rel="noreferrer">Cardano Improvement Proposals (CIP)</a></p><h2 id="cip-1694" tabindex="-1">CIP-1694 <a class="header-anchor" href="#cip-1694" aria-label="Permalink to &quot;CIP-1694&quot;">​</a></h2><p>La CIP-1694 est la proposition d’amélioration de Cardano qui définit son système de gouvernance sur chaîne. Elle introduit notamment les DReps, le Comité constitutionnel et les actions de gouvernance formelles.</p><p>→ <a href="https://cips.cardano.org/cip/CIP-1694" target="_blank" rel="noreferrer">CIP-1694 — Spécification officielle</a></p><h2 id="cip-19" tabindex="-1">CIP-19 <a class="header-anchor" href="#cip-19" aria-label="Permalink to &quot;CIP-19&quot;">​</a></h2><p>La CIP-19 est la spécification qui définit la structure binaire d’une adresse Cardano : le réseau auquel elle appartient, l’identifiant de paiement et, éventuellement, l’identifiant de staking.</p><p>→ <a href="https://cips.cardano.org/cip/CIP-19" target="_blank" rel="noreferrer">CIP-19 — Spécification officielle</a></p><h2 id="cip-20" tabindex="-1">CIP-20 <a class="header-anchor" href="#cip-20" aria-label="Permalink to &quot;CIP-20&quot;">​</a></h2><p>La CIP-20 définit un emplacement standard permettant d’ajouter un court message lisible par un humain aux métadonnées d’une transaction, afin qu’un mémo, une note ou un commentaire soit conservé sur la chaîne avec le paiement.</p><p>→ <a href="https://cips.cardano.org/cip/CIP-20" target="_blank" rel="noreferrer">CIP-20 — Spécification officielle</a></p><h2 id="cip-25" tabindex="-1">CIP-25 <a class="header-anchor" href="#cip-25" aria-label="Permalink to &quot;CIP-25&quot;">​</a></h2><p>La CIP-25 définit une convention permettant aux portefeuilles et aux places de marché de lire le nom, l’image et les attributs d’un NFT à partir des métadonnées associées au jeton lors de sa création.</p><p>→ <a href="https://cips.cardano.org/cip/CIP-25" target="_blank" rel="noreferrer">CIP-25 — Spécification officielle</a></p><h2 id="cip-30" tabindex="-1">CIP-30 <a class="header-anchor" href="#cip-30" aria-label="Permalink to &quot;CIP-30&quot;">​</a></h2><p>La CIP-30 est la norme qui permet à un site web de communiquer avec un portefeuille installé comme extension de navigateur. Les applications décentralisées peuvent ainsi demander des adresses, solliciter la signature d’une transaction et soumettre celle-ci, sans avoir à manipuler directement les clés de l’utilisateur.</p><p>→ <a href="https://cips.cardano.org/cip/CIP-30" target="_blank" rel="noreferrer">CIP-30 — Spécification officielle</a></p><h2 id="cip-68" tabindex="-1">CIP-68 <a class="header-anchor" href="#cip-68" aria-label="Permalink to &quot;CIP-68&quot;">​</a></h2><p>La CIP-68 est une norme de métadonnées pour les jetons qui stocke leurs métadonnées dans un datum sur chaîne qu’un contrat intelligent peut lire et mettre à jour, contrairement aux métadonnées de transaction utilisées par la CIP-25, qui sont figées.</p><p>→ <a href="https://cips.cardano.org/cip/CIP-0068" target="_blank" rel="noreferrer">CIP-68 — Spécification officielle</a></p><h2 id="cip-8" tabindex="-1">CIP-8 <a class="header-anchor" href="#cip-8" aria-label="Permalink to &quot;CIP-8&quot;">​</a></h2><p>La CIP-8 définit une norme permettant de signer des données arbitraires avec une clé de portefeuille. Elle peut servir à prouver le contrôle d’une adresse sans envoyer de transaction ni payer de frais.</p><p>→ <a href="https://cips.cardano.org/cip/CIP-0008" target="_blank" rel="noreferrer">CIP-8 — Spécification officielle</a></p><h2 id="cip-99" tabindex="-1">CIP-99 <a class="header-anchor" href="#cip-99" aria-label="Permalink to &quot;CIP-99&quot;">​</a></h2><p>La CIP-99 définit un mécanisme standard de réclamation permettant aux nouveaux utilisateurs de recevoir de l’ada ou des jetons lors d’un événement physique en scannant un code QR avec leur portefeuille, en remplacement des portefeuilles papier.</p><p>→ <a href="https://cips.cardano.org/cip/CIP-0099" target="_blank" rel="noreferrer">CIP-99 — Spécification officielle</a></p><h2 id="cip-113-—-programmable-token-like-assets-fr-actifs-de-type-jeton-programmables" tabindex="-1">CIP-113 — Programmable token-like assets (fr : Actifs de type jeton programmables) <a class="header-anchor" href="#cip-113-—-programmable-token-like-assets-fr-actifs-de-type-jeton-programmables" aria-label="Permalink to &quot;CIP-113 — Programmable token-like assets (fr : Actifs de type jeton programmables)&quot;">​</a></h2><p>La CIP-113 propose un standard pour les jetons programmables sur Cardano. Ces jetons nécessitent l’exécution réussie d’un script pour changer de propriétaire, ce qui permet d’appliquer des règles aux transferts, notamment des restrictions de transfert ou des mécanismes de gel et de saisie. Le standard utilise les fonctionnalités existantes de Cardano et ne nécessite pas de hard fork.</p><p>→ <a href="https://cips.cardano.org/cip/CIP-0113" target="_blank" rel="noreferrer">CIP-113 — Spécification officielle</a></p><p>→ <a href="https://developers.cardano.org/docs/developers/curriculum/native-tokens/programmable-tokens/" target="_blank" rel="noreferrer">Programmable Tokens — Cardano Developer Portal</a></p><h2 id="collateral-fr-garantie" tabindex="-1">Collateral (fr : Garantie) <a class="header-anchor" href="#collateral-fr-garantie" aria-label="Permalink to &quot;Collateral (fr : Garantie)&quot;">​</a></h2><p>Le collateral est un montant en ada qu’un portefeuille met de côté lors de la soumission d’une transaction Plutus. Cette garantie n’est perdue que si la validation du script sur la chaîne échoue.</p><h2 id="collateral-percentage-fr-pourcentage-de-garantie" tabindex="-1">Collateral Percentage (fr : Pourcentage de garantie) <a class="header-anchor" href="#collateral-percentage-fr-pourcentage-de-garantie" aria-label="Permalink to &quot;Collateral Percentage (fr : Pourcentage de garantie)&quot;">​</a></h2><p>Le Collateral Percentage est le paramètre du protocole qui détermine le montant de garantie à fournir par rapport aux frais d’une transaction Plutus. Sur le réseau principal, sa valeur est actuellement de 150, soit 150 % des frais.</p><h2 id="committee-minimum-size-fr-taille-minimale-du-comite" tabindex="-1">Committee Minimum Size (fr : Taille minimale du comité) <a class="header-anchor" href="#committee-minimum-size-fr-taille-minimale-du-comite" aria-label="Permalink to &quot;Committee Minimum Size (fr : Taille minimale du comité)&quot;">​</a></h2><p>Le Committee Minimum Size est le paramètre du protocole qui fixe le nombre minimal de membres du Comité constitutionnel devant occuper un siège pour que le comité soit opérationnel. Si le nombre de membres passe sous ce seuil, toute action de gouvernance nécessitant l’approbation du comité est bloquée jusqu’à ce que les sièges vacants soient pourvus.</p><h2 id="computation-layer-fr-couche-de-calcul" tabindex="-1">Computation Layer (fr : Couche de calcul) <a class="header-anchor" href="#computation-layer-fr-couche-de-calcul" aria-label="Permalink to &quot;Computation Layer (fr : Couche de calcul)&quot;">​</a></h2><p>La Computation Layer est un ancien concept architectural de la feuille de route initiale de Cardano, qui décrivait l’exécution des contrats intelligents comme une couche distincte de la couche de règlement.</p><h2 id="constitution-fr-constitution-de-cardano" tabindex="-1">Constitution (fr : Constitution de Cardano) <a class="header-anchor" href="#constitution-fr-constitution-de-cardano" aria-label="Permalink to &quot;Constitution (fr : Constitution de Cardano)&quot;">​</a></h2><p>La Constitution est le document qui définit les principes de gouvernance, les règles et les garde-fous de Cardano. Elle a été ratifiée sur chaîne en février 2025 et peut être modifiée au moyen d’actions de gouvernance portant sur sa mise à jour.</p><h2 id="constitutional-committee-fr-comite-constitutionnel" tabindex="-1">Constitutional Committee (fr : Comité constitutionnel) <a class="header-anchor" href="#constitutional-committee-fr-comite-constitutionnel" aria-label="Permalink to &quot;Constitutional Committee (fr : Comité constitutionnel)&quot;">​</a></h2><p>Le Comité constitutionnel est l’organe élu composé de sept membres qui vérifie la conformité des actions de gouvernance à la Constitution de Cardano. Il constitue un mécanisme de contrôle aux côtés des DReps et des opérateurs de pools de staking.</p><h2 id="controlled-stake-fr-stake-controle" tabindex="-1">Controlled Stake (fr : Stake contrôlé) <a class="header-anchor" href="#controlled-stake-fr-stake-controle" aria-label="Permalink to &quot;Controlled Stake (fr : Stake contrôlé)&quot;">​</a></h2><p>Le Controlled Stake désigne la quantité totale d’ada associée à un pool de staking, en combinant la mise personnelle de l’opérateur (<em>pledge</em>) et l’ensemble des délégations reçues.</p><h2 id="conway-era-fr-ere-conway" tabindex="-1">Conway Era (fr : Ère Conway) <a class="header-anchor" href="#conway-era-fr-ere-conway" aria-label="Permalink to &quot;Conway Era (fr : Ère Conway)&quot;">​</a></h2><p>L’ère Conway est l’ère du registre Cardano qui a introduit la gouvernance sur chaîne sur le réseau principal, conformément à la CIP-1694.</p>',57)])])}const f=a(i,[["render",o]]);export{m as __pageData,f as default};
